types.background='场景背景';
function activeBackgroundSettings(){const index=Math.max(0,scene().blocks.findIndex(b=>b.id===selected));return KotobaCore.backgroundSettings(KotobaCore.stageAt(project,scene(),index).backgroundBlock||scene().blocks.find(b=>b.type==='background')||{})}
function previewSceneBackgroundDialog(){const form=$('#dialogForm');if(!form?.querySelector('[data-scene-background-image]'))return;const image=asset(form.elements.asset.value),color=form.elements.color.value,fit=form.elements.fit.value;const preview=$('#sceneBackgroundPreview');preview.style.backgroundColor=color;const img=preview.querySelector('img');img.hidden=!image;if(image){if(img.getAttribute('src')!==image.data)img.src=image.data;img.style.objectFit=fit}preview.querySelector('span').hidden=!!image}
function openSceneBackground(assetId){const s=scene(),values={...activeBackgroundSettings(),...(assetId?{asset:assetId}:{})};dialog('场景背景 · 整个游戏画面',`<p>设置背景层，立绘和字幕继续显示在它上方。</p><div class="field"><label>背景图片（留空使用纯色）</label><select name="asset" data-scene-background-image>${assetOptions(values.asset)}</select></div><div id="sceneBackgroundPreview" class="scene-background-preview"><img alt="场景背景预览" hidden><span>纯色背景</span></div><button class="btn small" type="button" data-action="import-scene-background">导入本地背景图片</button><div class="field-row" style="margin-top:15px">${colorPalette('背景底色',values.color,'name="color" data-bg-preview')}<div class="field"><label>图片适配</label><select name="fit" data-bg-preview>${optionList({cover:'铺满画面（可能裁切）',contain:'完整显示（保留边缘）'},values.fit)}</select></div></div><div class="field"><label>应用范围</label><select name="scope">${block()?.type==='background'?'<option value="existing">修改选中的背景块</option>':''}<option value="opening">当前章节开场背景</option><option value="position">从选中剧情后开始切换</option><option value="chapter">全章统一（覆盖本章背景切换）</option></select></div><div class="field-row"><div class="field"><label>切换动画</label><select name="transition">${optionList(KotobaCore.effects,values.transition)}</select></div><div class="field"><label>动画时长（毫秒）</label><input name="duration" type="number" min="0" max="5000" step="100" value="${values.duration}"></div></div><p class="field-note">开场背景持续到后面的背景切换块。全章统一会替换本章已有的背景切换，可撤销。CG 会覆盖场景背景，隐藏 CG 后可看到当前背景。</p>`,'应用背景',f=>applySceneBackground(s.id,KotobaCore.backgroundSettings(Object.fromEntries(f)),f.get('scope')));previewSceneBackgroundDialog()}
function applySceneBackground(sid,settings,scope='opening'){const target=project.scenes.find(s=>s.id===sid);if(!target)return;change(()=>{stopContentPlayback();let b={id:uid(),type:'background',...KotobaCore.backgroundSettings(settings),text:'场景背景'};if(scope==='existing'&&target.blocks.find(b=>b.id===selected)?.type==='background'){b=target.blocks.find(b=>b.id===selected);Object.assign(b,settings)}else if(scope==='chapter'){target.blocks=target.blocks.filter(b=>b.type!=='background');target.blocks.unshift(b)}else if(scope==='position'){const i=target.blocks.findIndex(b=>b.id===selected);target.blocks.splice(i<0?target.blocks.length:i+1,0,b)}else{const firstContent=target.blocks.findIndex(b=>['dialogue','narration','choice','cg','effect','jump'].includes(b.type));const opening=target.blocks.slice(0,firstContent<0?target.blocks.length:firstContent).find(b=>b.type==='background');if(opening){Object.assign(opening,settings);b=opening}else target.blocks.unshift(b)}sceneId=sid;selected=b.id;view='script';mode='visual'});notify('场景背景已更新，整张画面的背景已生效')}
function importSceneBackground(){pickFile('image/png,image/jpeg,image/webp,image/gif',file=>{if(file.size>MAX_ASSET_BYTES){notify('请选择不超过 20 MB 的背景图片');return}if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)){notify('请选择 PNG、JPEG、WebP 或 GIF 图片');return}const reader=new FileReader();reader.onload=()=>{const item={id:uid(),name:file.name,type:'image',data:reader.result};change(()=>project.assets.push(item));const select=$('[data-scene-background-image]');if(select){select.innerHTML=assetOptions(item.id);previewSceneBackgroundDialog()}notify('背景图片已导入')};reader.onerror=()=>notify('背景图片读取失败，请重试');reader.readAsDataURL(file)})}
const sceneBackgroundDraw=draw,sceneBackgroundInspector=drawInspector,sceneBackgroundValidate=validateProject;
draw=function(){sceneBackgroundDraw();if(view==='script'){$('.tool-strip')?.insertAdjacentHTML('afterbegin','<button class="btn primary small" data-action="scene-background" title="设置开场、中途或全章背景">设置场景背景</button>');$('.preview-panel .panel-head')?.insertAdjacentHTML('beforeend','<button class="btn small" data-action="scene-background">场景背景设置</button>');for(const b of scene().blocks)if(b.type==='background'){const row=Array.from(document.querySelectorAll('.block')).find(el=>el.dataset.id===b.id),v=KotobaCore.backgroundSettings(b);if(row?.querySelector('.block-value'))row.querySelector('.block-value').textContent=asset(b.asset)?.name||'纯色背景 '+v.color}}if(view==='assets')document.querySelectorAll('.asset-card').forEach(card=>{const button=card.querySelector('[data-action="use-asset"]');if(asset(button?.dataset.id)?.type==='image'){button.textContent='插入背景切换';card.querySelector('.card-actions').insertAdjacentHTML('beforeend',`<button class="btn small" data-action="asset-scene-background" data-id="${esc(button.dataset.id)}">设为本章背景</button>`)}})};
drawInspector=function(){sceneBackgroundInspector();const b=block();if(b?.type==='background'){const v=KotobaCore.backgroundSettings(b);$('#inspector').insertAdjacentHTML('afterbegin',`<div class="field-row"><div class="field"><label>画面底色</label><input type="color" data-scene-background="color" value="${v.color}"></div><div class="field"><label>画面适配</label><select data-scene-background="fit">${optionList({cover:'铺满画面',contain:'完整显示'},v.fit)}</select></div></div><button class="btn small" data-action="scene-background">选择或导入画面背景</button><p class="field-note">这是整个游戏画面的背景层，角色立绘和字幕会显示在其上方。</p>`)}};
validateProject=function(p){sceneBackgroundValidate(p);for(const s of p.scenes)for(const b of s.blocks)if(b.type==='background'){if(b.fit!==undefined&&!['contain','cover'].includes(b.fit))throw Error('背景图片适配无效');if(b.color!==undefined&&!/^#[a-f\d]{6}$/i.test(b.color))throw Error('背景底色格式无效')}return p};
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]'),action=button?.dataset.action;if(!['scene-background','asset-scene-background','import-scene-background'].includes(action))return;e.preventDefault();e.stopImmediatePropagation();if(action==='scene-background')openSceneBackground();if(action==='asset-scene-background')openSceneBackground(button.dataset.id);if(action==='import-scene-background')importSceneBackground()},true);
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-scene-background-image')||e.target.hasAttribute('data-bg-preview'))previewSceneBackgroundDialog();if(e.target.dataset.sceneBackground&&block()?.type==='background')change(()=>block()[e.target.dataset.sceneBackground]=e.target.value)});
document.addEventListener('input',e=>{if(e.target.hasAttribute('data-bg-preview'))previewSceneBackgroundDialog()});
draw();
